#!/bin/bash
# Compact OCR view of a variant: drops the essay boilerplate and footer lines. Usage: view.sh R N [from] [to]
R=$1; N=$2; A=${3:-0}; B=${4:-9999}
python3 -I $R/tools/show.py $R $N | grep -v "^[0-9]* \(Сформулируйте\|Прокомментируйте\|в комментарий\|понимания\|смысловую\|по проблеме\|на читательский\|примеры-аргументы\|графический\|информации\|Объём\|Работа, написанная\|несамостоятельно\|переписанный\|комментариев\|Сочинение пишите\|литературного языка\|Не забудьте\|с инструкцией\|Проверьте, чтобы\|соответствующего задания\|записан в строке\|Для ответа на это\|Часть 2\|исходного текста\|историко-культурный\|Ответ\)" | awk -v a=$A -v b=$B '$1>=a && $1<=b'
